('preemie_backfill_error','uz','Xato: ','app'),
('preemie_backfill_preterm','uz','Muddatidan oldin','app'),
('preemie_backfill_q','uz','{name} muddatida tug''ilganmi?','app'),
('preemie_backfill_save','uz','Saqlash','app'),
('preemie_backfill_saved','uz','Saqlandi','app'),
('preemie_backfill_sub','uz','Muddatidan oldin tug''ilgan chaqaloqlarning rivojlanishi va o''sishi korreksiyalangan yosh asosida kuzatiladi.','app'),
('preemie_backfill_term','uz','Ha, muddatida (37+ hafta)','app'),
('preemie_backfill_weeks','uz','haftalikda tug''ilgan','app'),
('preemie_c1_b','uz','Korreksiyalangan yosh = haqiqiy (xronologik) yosh − muddatidan oldin tug''ilgan davr. Masalan, chaqaloq 2 oy oldin tug''ilgan va hozir 5 oylik bo''lsa, korreksiyalangan yoshi 3 oy bo''ladi. Amalda bu kutilgan tug''ruq sanasidan (EDD) bugungacha o''tgan vaqtga teng.','app'),
('preemie_c1_t','uz','Qanday hisoblanadi?','app'),
('preemie_c2_b','uz','Rivojlanish bosqichlari (ag''darilish, o''tirish, yurish), o''sish egri chiziqlari (vazn/bo''y percentillari), o''yin va mashg''ulot tanlovi — barchasi korreksiyalangan yosh asosida baholanishi kerak. Anacan buni avtomatik qo''llaydi: o''sish grafigi, kundalik rivojlanish kontenti va o''yin tavsiyalari korreksiyalangan yosh asosida ishlaydi.','app'),
('preemie_c2_t','uz','Qayerda qo''llanadi?','app'),
('preemie_c3_b','uz','Emlashlar korreksiyalangan yoshga ko''ra EMAS, haqiqiy tug''ilgan sanaga ko''ra qilinadi (xalqaro standart — JSST/AAP). Emlash taqvimini kechiktirmang: muddatidan oldin tug''ilgan chaqaloqlar infeksiyalarga sezgirroq bo''ladi va himoyaga ertaroq muhtoj.','app'),
('preemie_c3_t','uz','Qayerda qo''llanMAYDI?','app'),
('preemie_c4_b','uz','Odatda korreksiyalangan yosh 24 oyga (2 yosh) yetguncha. Bu yoshdan keyin aksariyat chaqaloqlar tengdoshlariga yetib oladi va korreksiyaga ehtiyoj qolmaydi. Ayrim hollarda (juda erta tug''ilganlarda) shifokor 3 yoshgacha davom ettirishni tavsiya qilishi mumkin.','app'),
('preemie_c4_t','uz','Qachongacha?','app'),
('preemie_corrected_label','uz','Korreksiyalangan yosh','app'),
('preemie_corrected_short','uz','korreksiya','app'),
('preemie_d1_b','uz','15-20 soniyadan uzoq nafas to''xtashi (apnoe), ingrash bilan nafas olish, burun qanotlarining kengayishi, qovurg''alar orasining ichkariga tortilishi, lablar/yuzning ko''karishi — darhol tez yordam chaqiring.','app'),
('preemie_d1_t','uz','Nafas olish muammolari','app'),
('preemie_d2_b','uz','Qo''ltiq osti harorati 36.4°C dan past yoki 38°C dan yuqori bo''lsa — muddatidan oldin tug''ilgan chaqaloqda har ikkala holat ham jiddiy hisoblanadi va darhol shifokorga xabar berish kerak. Isitmani uyda "tushirishga" urinib kutmang.','app'),
('preemie_d2_t','uz','Harorat','app'),
('preemie_d3_b','uz','Ketma-ket 2-3 marta ovqatlanishdan bosh tortish, odatdagidan tashqari holsizlik/uyg''onmaslik, tinimsiz qusish (ayniqsa yashil rangli) — shoshilinch tekshiruvni talab qiladi.','app'),
('preemie_d3_t','uz','Ovqatlanish va faollik','app'),
('preemie_d4_b','uz','24 soatda 4 tadan kam ho''l taglik, ichkariga botgan liqildoq, yig''laganda ko''z yoshi chiqmasligi — suvsizlanish belgilaridir. Anacan''dagi "Xavf belgilari" vositasida to''liq ro''yxat mavjud.','app'),
('preemie_d4_t','uz','Suvsizlanish belgilari','app'),
('preemie_dash_entry_sub','uz','NICU, kenguru parvarishi, ovqatlantirish va korreksiyalangan yosh','app'),
('preemie_dash_entry_title','uz','Muddatidan oldin tug''ilganlar qo''llanmasi','app'),
('preemie_f1_b','uz','Chaqaloq hali ema olmasa ham, tug''ruqdan keyingi dastlabki 6 soat ichida sut sog''ishni boshlang va kuniga 8-10 marta (tunda ham) davom ettiring — bu sut ajralishini saqlaydi. Og''iz sutining ilk tomchisi ham qadrli; uni NICU''ga yetkazing.','app'),
('preemie_f1_t','uz','Dastlabki kunlar: sog''ish tartibi','app'),
('preemie_f2_b','uz','Emish-yutish-nafas olish muvofiqligi odatda 32-34 haftalikda shakllanadi. O''tish asta-sekin bo''ladi: avval zond orqali ovqatlantirish paytida ko''krak bilan "tanishish" (oziqlantirmaydigan emish), keyin qisqa emizishlar, so''ng to''liq o''tish. Sabrli bo''ling — bu ko''nikma mashq talab qiladi.','app'),
('preemie_f2_t','uz','Zonddan ko''krakka o''tish bosqichma-bosqich','app'),
('preemie_f3_b','uz','Ayrim muddatidan oldin tug''ilgan chaqaloqlarga ona sutiga qo''shimcha kaloriya, oqsil va minerallar beruvchi kuchaytirgich buyuriladi — bu ona suti "yetarli emas" degani emas, shunchaki bunday chaqaloqning ehtiyoji yuqoriroq. Faqat shifokor tavsiyasi bilan qo''llanadi.','app'),
('preemie_f3_t','uz','Kuchaytirgich (fortifier) nima?','app'),
('preemie_f4_b','uz','Vazn ortishi muddatidan oldin tug''ilgan chaqaloqning eng muhim ko''rsatkichlaridan biridir. Anacan''ning O''sish kuzatuvchisiga o''lchovlarni kiriting — grafik avtomatik ravishda korreksiyalangan yosh asosida tuziladi, ya''ni chaqalog''ingiz tengdoshlari bilan to''g''ri taqqoslanadi.','app'),
('preemie_f4_t','uz','Vaznni kuzatish','app'),
('preemie_hub_disclaimer','uz','Bu ma''lumotlar ma''rifiy xususiyatga ega bo''lib, shifokor ko''rigini/maslahatini almashtirmaydi. Chaqalog''ingizga oid barcha qarorlarni pediatringiz bilan birga qabul qiling.','app'),
('preemie_hub_eyebrow','uz','Muddatidan oldin tug''ilganlar','app'),
('preemie_hub_generic_intro','uz','Dunyoda har 10 chaqaloqdan ~1-i muddatidan oldin (37 haftadan avval) tug''iladi. Bu qo''llanma NICU kunlaridan uydagi dastlabki oylargacha sizga yo''l ko''rsatadi.','app'),
('preemie_hub_status_chrono','uz','Haqiqiy yosh','app'),
('preemie_hub_status_corrected','uz','Tuzatilgan yosh','app'),
('preemie_hub_status_note','uz','O''sish grafigi, rivojlanish materiallari va o''yin tavsiyalari avtomatik ravishda tuzatilgan yosh bo''yicha ishlaydi.','app'),
('preemie_hub_title','uz','Chala tug''ilganlar qo''llanmasi','app'),
('preemie_i1_b','uz','Chaqaloqqa tegishdan oldin har bir kishi qo''lini sovunlab yuvishi yoki dezinfeksiya qilishi shart — istisnosiz. Bu eng oddiy va samarali himoyadir.','app'),
('preemie_i1_t','uz','Oltin qoida: qo''l yuvish','app'),
('preemie_i2_b','uz','Shamollagan, yo''talayotgan yoki isitmasi bor hech kim chaqaloqqa yaqinlashmasligi kerak. Chaqaloqning yuzi va qo''llaridan o''pishga ruxsat bermang. Dastlabki oylarda tashrif buyuruvchilar sonini minimal darajada saqlang.','app'),
('preemie_i2_t','uz','Tashrif buyuruvchilar qoidalari','app'),
('preemie_i3_b','uz','Sigaret tutuni (kiyimdagi qoldiqlar ham) chala tug''ilgan chaqaloqda nafas olish muammolari va chaqaloqning to''satdan o''limi sindromi (SIDS) xavfini keskin oshiradi. Uyda va chaqaloq yonida chekishni qat''iyan taqiqlang.','app'),
('preemie_i3_t','uz','Sigaret tutuni — qat''iyan taqiqlanadi','app'),
('preemie_i4_b','uz','RSV (respirator-sinsitial virus) chala tug''ilgan chaqaloqlar uchun eng xavfli mavsumiy virusdir. Kuz-qish oylarida odam gavjum yopiq joylardan (savdo markazi, to''y) uzoq turing. Chaqalog''ingiz RSVdan himoyalovchi immunizatsiyaga mos kelish-kelmasligini pediatringiz bilan muhokama qiling.','app'),
('preemie_i4_t','uz','RSV mavsumida (kuz-qish) ehtiyot bo''ling','app'),
('preemie_i5_b','uz','Chala tug''ilgan chaqaloqlar vaksinalarni haqiqiy (xronologik) yoshiga ko''ra, odatiy taqvim asosida oladi — tuzatilgan yosh kutilmaydi. Oila a''zolarining gripp va ko''kyo''talga qarshi vaksina olishi ham chaqaloqni bilvosita himoya qiladi ("kokon strategiyasi").','app'),
('preemie_i5_t','uz','Vaksinalarni kechiktirmang','app'),
('preemie_k1_b','uz','Chaqaloq harorati, yurak urishi va nafas olishini barqarorlashtiradi, vazn ortishini tezlashtiradi, uyqusini chuqurlashtiradi, ona suti ajralishini ko''paytiradi hamda ota-ona va chaqaloq o''rtasidagi rishtani mustahkamlaydi. JSST (WHO) kenguru parvarishini barcha chala tug''ilgan chaqaloqlarga tavsiya qiladi.','app'),
('preemie_k1_t','uz','Foydalari (ilmiy isbotlangan)','app'),
('preemie_k2_b','uz','Chaqaloq faqat taglikda ko''kragingizga tik holatda qo''yiladi, boshi yon tomonga buriladi (nafas yo''li ochiq), ustidan yumshoq yopqich yopiladi. Qulay o''tirib, dam oling. NICUda bo''lsangiz, vaqti va tartibini tibbiyot xodimlari bilan kelishib oling.','app'),
('preemie_k2_t','uz','Qanday bajariladi?','app'),
('preemie_k3_b','uz','Imkon qadar ko''p — har bir seans ideal holatda kamida 60 daqiqa davom etishi kerak (qisqa seanslar chaqaloqni charchatmasligi mumkin, ammo ko''chirish jarayoni stress tug''diradi). Buni kundalik odatga aylantiring.','app'),
('preemie_k3_t','uz','Qancha vaqt?','app')
ON CONFLICT (key, lang) DO UPDATE SET value = EXCLUDED.value, updated_at = now();

INSERT INTO public.translations (key, lang, value, namespace) VALUES
('preemie_k4_b','uz','Kenguru parvarishi faqat ona uchun emas — otaning ham teri-teriga aloqasi birdek foydali va unga chaqaloq bilan erta rishta o''rnatishga yordam beradi. Navbatlashing.','app'),
('preemie_k4_t','uz','Ota ham bajara oladi','app'),
('preemie_n1_b','uz','Monitorlar yurak urishi, nafas olish va kislorod darajasini kuzatadi; oziqlantirish zondi chaqaloq emishni o''rganguncha sut beradi; CPAP nafas olishni qo''llab-quvvatlaydi; inkubator issiqlikni saqlaydi. Signal tovushlari ko''pincha kichik o''zgarishlarni bildiradi — har bir signal xavf degani emas.','app'),
('preemie_n1_t','uz','Uskunalar sizni qo''rqitmasin','app'),
('preemie_n2_b','uz','Ovozingiz, teginishingiz va ona suti — hech qanday uskuna bera olmaydigan narsalardir. Chaqalog''ingiz bilan gaplashing, qo''shiq ayting, imkoni bo''lganda teri-teriga aloqa qiling. Tibbiyot xodimlaridan chaqaloq parvarishida qatnashishga ruxsat so''rang (taglikni almashtirish, haroratni o''lchash).','app'),
('preemie_n2_t','uz','Ota-ona sifatidagi rolingiz katta','app'),
('preemie_n3_b','uz','Har kuni so''rashingiz mumkin: bugun vazni qancha? Oziqlanishi qanday ketyapti? Bugungi reja qanday? Uyga chiqish uchun qaysi bosqichlar qoldi? Savollaringizni telefonga yozib qo''ying — uchrashuvda unutib qo''ymaysiz.','app'),
('preemie_n3_t','uz','Savol berishdan tortinmang','app'),
('preemie_n4_b','uz','Odatda chaqaloq quyidagi hollarda uyga chiqishga tayyor bo''ladi: tana haroratini o''zi saqlay olsa, zondsiz (ko''krak yoki butilka orqali) oziqlana olsa, vazni barqaror oshsa va nafas olishdagi tanaffuslar (apnoe) o''tib ketsa. Bu odatda dastlabki kutilgan tug''ruq sanasiga (EDDga) yaqin vaqtga to''g''ri keladi.','app'),
('preemie_n4_t','uz','Uyga chiqish mezonlari','app'),
('preemie_n5_b','uz','NICUdagi yo''l marafondir, sprint emas. Ovqatlaning, uxlang, navbatlashing. Yig''lash odatiy hol. Anacan-ning Ruhiy salomatlik vositasidan foydalaning va Hamjamiyatdagi boshqa chala tug''ilgan chaqaloqlarning ota-onalari bilan bog''laning — bu yo''lni bosib o''tayotgan yagona inson siz emassiz.','app'),
('preemie_n5_t','uz','O''zingizga ham g''amxo''rlik qiling','app'),
